1	//! Pure extraction for one TypeScript or JavaScript file.
2	//!
3	//! The parse owns its arena. Everything leaving this module is owned data, so no arena-borrowed node escapes.
4	
5	use std::thread;
6	
7	use camino::Utf8Path;
8	use oxc_allocator::Allocator;
9	use oxc_ast::ast::{
10	    BindingPattern, Class, Declaration, ExportAllDeclaration, ExportDeclaration, ExportDefaultDeclaration,
11	    ExportDefaultDeclarationKind, ExportFromDeclaration, ExportNamedDeclaration, Function, ImportDeclaration,
12	    ImportDeclarationSpecifier, JSXAttributeItem, JSXAttributeName, JSXAttributeValue, JSXElement, JSXElementName,
13	    JSXMemberExpression, JSXMemberExpressionObject, ModuleExportName, Program, Statement, VariableDeclaration,
14	};
15	use oxc_ast_visit::{Visit, walk};
16	use oxc_parser::{ParseOptions, Parser};
17	use oxc_span::{GetSpan, SourceType, Span};
18	
19	use crate::analysis::AnalysisProfile;
20	use crate::types::{
21	    BindingKind, CodeBlock, DependencyBinding, DependencyRecord, DependencyTarget, ExportRecord, JsxAttribute,
22	    JsxElementEntry, SymbolEntry, SymbolKind,
23	};
24	
25	/// Files with more bracket nesting than this are not parsed. Real code stays far below it; turning such a file away
26	/// early saves touching hundreds of megabytes of stack on a parse that recovers nothing useful.
27	const MAX_SOURCE_NESTING_DEPTH: usize = 256;
28	
29	/// Stack reserved per byte of source. A stack overflow aborts the process, so the stack must be big enough before the
30	/// parse starts. Each level of the parser's or the extractor's recursion consumes at least one byte, and the costliest
31	/// level measured, a `[` in a type, uses 1.7 KB of stack optimized and 4.6 KB unoptimized: this is over twice that.
32	const STACK_PER_SOURCE_BYTE: usize = if cfg!(debug_assertions) { 12 << 10 } else { 4 << 10 };
33	
34	/// Stack for what does not grow with the source.
35	const BASE_STACK: usize = 8 << 20;
36	
37	/// The most stack one parse reserves. Only touched pages are committed, but a file that defeats the nesting scan can
38	/// touch about half of it, so this also bounds that file's memory.
39	const MAX_STACK: usize = 1 << 30;
40	
41	/// The longest source that is parsed; a longer one could need more than [`MAX_STACK`].
42	pub(super) const MAX_PARSED_SOURCE_LEN: usize = (MAX_STACK - BASE_STACK) / STACK_PER_SOURCE_BYTE;
43	
44	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
45	#[derive(Debug, Default)]
46	pub(super) struct Extraction {
47	    pub(super) symbols: Vec<SymbolEntry>,
48	    pub(super) dependencies: Vec<DependencyRecord>,
49	    pub(super) exports: Vec<ExportRecord>,
50	    pub(super) blocks: Vec<CodeBlock>,
51	    pub(super) jsx_elements: Vec<JsxElementEntry>,
52	    pub(super) type_only_imports: Vec<String>,
53	    pub(super) had_parse_errors: bool,
54	}
55	
56	impl Extraction {
57	    /// The result for a file that could not be analyzed: no data, flagged as having errors.
58	    fn degraded() -> Self {
59	        Self { had_parse_errors: true, ..Self::default() }
60	    }
61	}
62	
63	/// Extracts what `profile` asks for from `source`.
64	///
65	/// A file too long to be sure of its stack, one with too much bracket nesting, or one whose parse or extraction
66	/// panics, yields [`Extraction::degraded`].
67	pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
68	    if source.len() > MAX_PARSED_SOURCE_LEN || max_bracket_nesting_depth(source) > MAX_SOURCE_NESTING_DEPTH {
69	        return Extraction::degraded();
70	    }
71	    let stack_size = BASE_STACK + source.len() * STACK_PER_SOURCE_BYTE;
72	    guarded(stack_size, || parse_and_extract(path, source, profile))
73	}
74	
75	/// Runs `run` on its own thread with `stack_size` bytes of stack. A panic, or a thread that cannot be started, yields
76	/// [`Extraction::degraded`].
77	fn guarded(stack_size: usize, run: impl FnOnce() -> Extraction + Send) -> Extraction {
78	    thread::scope(|scope| {
79	        let builder = thread::Builder::new().name("monokl-parse".to_owned()).stack_size(stack_size);
80	        let Ok(handle) = builder.spawn_scoped(scope, run) else { return Extraction::degraded() };
81	        // The closure's output is discarded on a panic, so no torn state is observable afterwards.
82	        handle.join().unwrap_or_else(|_| Extraction::degraded())
83	    })
84	}
85	
86	/// The deepest bracket nesting in `source`, skipping comments and string, template and regex literals.
87	///
88	/// A cheap linear scan, not a parse: it tells a regex literal from a division by the character before it and does not
89	/// look inside templates or JSX text, so it can miscount. The stack each parse gets does not depend on it.
90	fn max_bracket_nesting_depth(source: &str) -> usize {
91	    let bytes = source.as_bytes();
92	    let (mut depth, mut max_depth, mut i) = (0usize, 0usize, 0usize);
93	    let mut previous = None;
94	    while i < bytes.len() {
95	        let byte = bytes[i];
96	        match byte {
97	            b'/' if bytes.get(i + 1) == Some(&b'/') => {
98	                while i < bytes.len() && bytes[i] != b'\n' {
99	                    i += 1;
100	                }
101	                continue;
102	            }
103	            b'/' if bytes.get(i + 1) == Some(&b'*') => {
104	                i += 2;
105	                while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
106	                    i += 1;
107	                }
108	                i += 2;
109	                continue;
110	            }
111	            b'/' if previous.is_none_or(|before: u8| b"(,=:[!&|?{};+-*%<>~^".contains(&before)) => {
112	                i = regex_end(bytes, i + 1);
113	            }
114	            quote @ (b'\'' | b'"' | b'`') => i = string_end(bytes, i + 1, quote),
115	            b'(' | b'{' | b'[' => {
116	                depth += 1;
117	                max_depth = max_depth.max(depth);
118	                i += 1;
119	            }
120	            b')' | b'}' | b']' => {
121	                depth = depth.saturating_sub(1);
122	                i += 1;
123	            }
124	            _ => i += 1,
125	        }
126	        if !byte.is_ascii_whitespace() {
127	            previous = Some(byte);
128	        }
129	    }
130	    max_depth
131	}
132	
133	/// The index just past the string or template literal whose body starts at `i`. Quoted strings cannot span lines, so
134	/// a quote the scan mistook for one hides at most the rest of its line.
135	fn string_end(bytes: &[u8], mut i: usize, quote: u8) -> usize {
136	    while i < bytes.len() && bytes[i] != quote {
137	        if quote != b'`' && bytes[i] == b'\n' {
138	            return i;
139	        }
140	        i += if bytes[i] == b'\\' { 2 } else { 1 };
141	    }
142	    i + 1
143	}
144	
145	/// The index just past the regex literal whose body starts at `i`, or of the line break that ends it early.
146	fn regex_end(bytes: &[u8], mut i: usize) -> usize {
147	    let mut in_class = false;
148	    while i < bytes.len() {
149	        match bytes[i] {
150	            b'\\' => i += 1,
151	            b'\n' => return i,
152	            b'[' => in_class = true,
153	            b']' => in_class = false,
154	            b'/' if !in_class => return i + 1,
155	            _ => {}
156	        }
157	        i += 1;
158	    }
159	    i
160	}
161	
162	/// JavaScript files may hold JSX whatever their extension; TypeScript files only in `.tsx`, since `<T>x` is a cast
163	/// elsewhere.
164	fn source_type_for(path: &Utf8Path) -> SourceType {
165	    let source_type = SourceType::from_path(path.as_std_path()).unwrap_or_else(|_| SourceType::ts());
166	    if source_type.is_javascript() { source_type.with_jsx(true) } else { source_type }
167	}
168	
169	fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
170	    let allocator = Allocator::default();
171	    // Parentheses carry no meaning here and a `ParenthesizedExpression` node would only add a level to every walk.
172	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
173	    let parsed = Parser::new(&allocator, source, source_type_for(path)).with_options(options).parse();
174	    // The recovered program is still used below, so record the diagnostics rather than discarding the parse.
175	    let had_parse_errors = parsed.fatal_error || !parsed.diagnostics.is_empty();
176	
177	    let mut extractor = Extractor { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
178	    for statement in &parsed.program.body {
179	        extractor.statement(statement);
180	    }
181	    if profile == AnalysisProfile::Full {
182	        extractor.jsx(&parsed.program);
183	    }
184	    Extraction { had_parse_errors, ..extractor.out }
185	}
186	
187	/// Maps byte offsets to 1-based line numbers.
188	struct LineIndex {
189	    newlines: Vec<usize>,
190	}
191	
192	impl LineIndex {
193	    fn new(source: &str) -> Self {
194	        Self { newlines: source.bytes().enumerate().filter(|&(_, byte)| byte == b'\n').map(|(i, _)| i).collect() }
195	    }
196	
197	    fn line(&self, offset: u32) -> usize {
198	        self.newlines.partition_point(|&newline| newline < offset as usize) + 1
199	    }
200	}
201	
202	struct Extractor<'s> {
203	    path: &'s Utf8Path,
204	    source: &'s str,
205	    profile: AnalysisProfile,
206	    lines: LineIndex,
207	    out: Extraction,
208	}
209	
210	impl Extractor<'_> {
211	    fn structural(&self) -> bool {
212	        self.profile != AnalysisProfile::Dependencies
213	    }
214	
215	    fn text(&self, span: Span) -> &str {
216	        self.source.get(span.start as usize..span.end as usize).unwrap_or_default()
217	    }
218	
219	    fn statement(&mut self, statement: &Statement<'_>) {
220	        match statement {
221	            Statement::ImportDeclaration(decl) => self.import(decl),
222	            Statement::ExportDeclaration(decl) => self.export_declaration(decl),
223	            Statement::ExportNamedDeclaration(decl) => self.export_named(decl),
224	            Statement::ExportFromDeclaration(decl) => self.export_from(decl),
225	            Statement::ExportDefaultDeclaration(decl) => self.export_default(decl),
226	            Statement::ExportAllDeclaration(decl) => self.export_all(decl),
227	            Statement::FunctionDeclaration(function) => {
228	                self.function(function);
229	            }
230	            Statement::ClassDeclaration(class) => {
231	                self.class(class);
232	            }
233	            Statement::TSInterfaceDeclaration(decl) => {
234	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
235	            }
236	            Statement::TSTypeAliasDeclaration(decl) => {
237	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
238	            }
239	            Statement::TSEnumDeclaration(decl) => {
240	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
241	            }
242	            Statement::VariableDeclaration(decl) => {
243	                self.variables(decl);
244	            }
245	            _ => {}
246	        }
247	        if self.profile == AnalysisProfile::Full {
248	            self.block(statement);
249	        }
250	    }
251	
252	    fn symbol(&mut self, name: &str, kind: SymbolKind, span: Span, signature: Option<String>) {
253	        if !self.structural() {
254	            return;
255	        }
256	        self.out.symbols.push(SymbolEntry {
257	            name: name.to_owned(),
258	            kind,
259	            line: self.lines.line(span.start),
260	            signature,
261	            owner: None,
262	            trait_impl: None,
263	            visibility: None,
264	            kind_detail: None,
265	        });
266	    }
267	
268	    fn export(&mut self, name: String, span: Span, re_export: bool) {
269	        if !self.structural() {
270	            return;
271	        }
272	        self.out.exports.push(ExportRecord { name, line: self.lines.line(span.start), re_export });
273	    }
274	
275	    /// Records a function symbol and returns its name; anonymous functions have none.
276	    fn function(&mut self, function: &Function<'_>) -> Option<String> {
277	        let name = function.id.as_ref()?.name.as_str();
278	        let signature = self.function_signature(function);
279	        self.symbol(name, SymbolKind::Function, function.span, Some(signature));
280	        Some(name.to_owned())
281	    }
282	
283	    /// The function's text up to its body, on one line: `function f(a: A): B`.
284	    fn function_signature(&self, function: &Function<'_>) -> String {
285	        let end = function.body.as_ref().map_or(function.span.end, |body| body.span.start);
286	        let head = self.text(Span::new(function.span.start, end));
287	        head.split_whitespace().collect::<Vec<_>>().join(" ").trim_end_matches(';').trim_end().to_owned()
288	    }
289	
290	    fn class(&mut self, class: &Class<'_>) -> Option<String> {
291	        let name = class.id.as_ref()?.name.as_str();
292	        self.symbol(name, SymbolKind::Class, class.span, None);
293	        Some(name.to_owned())
294	    }
295	
296	    fn variables(&mut self, decl: &VariableDeclaration<'_>) -> Vec<String> {
297	        let mut names = Vec::new();
298	        for declarator in &decl.declarations {
299	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
300	                self.symbol(id.name.as_str(), SymbolKind::Variable, declarator.span, None);
301	                names.push(id.name.as_str().to_owned());
302	            }
303	        }
304	        names
305	    }
306	
307	    /// Records the symbols a declaration introduces and returns their names.
308	    fn declaration(&mut self, decl: &Declaration<'_>) -> Vec<String> {
309	        match decl {
310	            Declaration::FunctionDeclaration(function) => self.function(function).into_iter().collect(),
311	            Declaration::ClassDeclaration(class) => self.class(class).into_iter().collect(),
312	            Declaration::TSInterfaceDeclaration(decl) => {
313	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
314	                vec![decl.id.name.as_str().to_owned()]
315	            }
316	            Declaration::TSTypeAliasDeclaration(decl) => {
317	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
318	                vec![decl.id.name.as_str().to_owned()]
319	            }
320	            Declaration::TSEnumDeclaration(decl) => {
321	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
322	                vec![decl.id.name.as_str().to_owned()]
323	            }
324	            Declaration::VariableDeclaration(decl) => self.variables(decl),
325	            Declaration::TSExternalModuleDeclaration(_)
326	            | Declaration::TSNamespaceDeclaration(_)
327	            | Declaration::TSGlobalDeclaration(_)
328	            | Declaration::TSImportEqualsDeclaration(_) => Vec::new(),
329	        }
330	    }

