75	/// Runs `run` on its own thread with `stack_size` bytes of stack. A panic, or a thread that cannot be started, yields
76	/// [`Extraction::degraded`].
77	fn guarded(stack_size: usize, run: impl FnOnce() -> Extraction + Send) -> Extraction {
78	    thread::scope(|scope| {
79	        let builder = thread::Builder::new().name("monokl-parse".to_owned()).stack_size(stack_size);
80	        let Ok(handle) = builder.spawn_scoped(scope, run) else { return Extraction::degraded() };
81	        // The closure's output is discarded on a panic, so no torn state is observable afterwards.
82	        handle.join().unwrap_or_else(|_| Extraction::degraded())
